<?php $this->layout('layouts/default', compact('title', 'description', 'canonical', 'robots', 'ogUrl', 'ogType', 'ogImage')); ?>
<div class="help-shell help-article-shell"><?php $this->insert('components/breadcrumb', ['items' => [['label' => $article['product_name'], 'url' => '/help/products/' . rawurlencode((string) $article['product_slug'])], ['label' => $article['category_name'], 'url' => '/help/categories/' . rawurlencode((string) $article['category_slug'])], ['label' => $article['title']]]]); ?>
<div class="help-article-layout"><article class="help-article"><header><p class="help-eyebrow"><?= $this->e((string) $article['product_name']) ?> · <?= $this->e((string) $article['category_name']) ?></p><h1><?= $this->e((string) $article['title']) ?></h1><?php if (!empty($article['excerpt'])): ?><p class="article-lead"><?= $this->e((string) $article['excerpt']) ?></p><?php endif; ?><div class="article-meta"><span><i class="icon-time-outline" aria-hidden="true"></i> <?= max(1, (int) $article['reading_time']) ?> min de leitura</span><span>Atualizado em <?= $this->e(date('d/m/Y', strtotime((string) $article['updated_at']))) ?></span></div><?php if (!empty($article['cover_media_id'])): ?><figure class="article-cover"><img src="/media/<?= (int) $article['cover_media_id'] ?>" alt="<?= $this->e((string) ($article['cover_alt'] ?: $article['title'])) ?>"></figure><?php endif; ?></header><div class="help-rich-content"><?= $article['rendered_content'] ?></div><?php if ($tags !== []): ?><footer class="article-tags" aria-label="Tags"><?php foreach ($tags as $tag): ?><span><?= $this->e((string) $tag['name']) ?></span><?php endforeach; ?></footer><?php endif; ?></article>
<aside class="help-article-aside"><?php if ($toc !== []): ?><nav class="help-toc" aria-label="Nesta página"><strong>Nesta página</strong><?php foreach ($toc as $entry): ?><a class="level-<?= (int) $entry['level'] ?>" href="#<?= $this->e($entry['id']) ?>"><?= $this->e($entry['label']) ?></a><?php endforeach; ?></nav><?php endif; ?><div class="help-contact-card"><i class="icon-chatbubbles-outline" aria-hidden="true"></i><strong>Ainda precisa de ajuda?</strong><p>Fale com a equipe Moves.</p><a href="/contato">Entrar em contato</a></div></aside></div>
<?php if ($related !== []): ?><section class="help-related"><header class="section-heading"><div><p class="help-eyebrow">CONTINUE EXPLORANDO</p><h2>Artigos relacionados</h2></div></header><?php $this->insert('components/article-list', ['articles' => $related]); ?></section><?php endif; ?></div>
